1: // Gamification rules: stars (FR-MISI-06), score/XP/rank (FR-MISI-07), badges (FR-MISI-08),
2: // level unlocking (FR-MISI-09) and concept mastery (FR-DASH-03). Pure functions only.
3: 
4: import { LEVELS, MISSIONS, missionsByLevel } from "@/content/missions";
5: import type { Concept } from "./types";
6: 
7: export const UNLOCK_RATIO = 0.7;
8: 
9: export interface StarInput {
10:   blocksUsed: number;
11:   optimalBlocks: number;
12:   failedAttempts: number;
13:   hintsUsed: number;
14:   maxHintLevel: number;
15: }
16: 
17: /**
18:  * 1–3 stars. Penalty points: inefficient solution (+1), failed attempts (+0.5 each after
19:  * the first, max +1), hints (+0.5 each, max +1.5, a level-3 hint adds +0.5).
20:  */
21: export function computeStars(i: StarInput): number {
22:   let penalty = 0;
23:   if (i.blocksUsed > i.optimalBlocks) penalty += 1;
24:   penalty += Math.min(1, Math.max(0, i.failedAttempts - 1) * 0.5);
25:   penalty += Math.min(1.5, i.hintsUsed * 0.5 + (i.maxHintLevel >= 3 ? 0.5 : 0));
26:   return Math.max(1, Math.min(3, 3 - Math.floor(penalty)));
27: }
28: 
29: export function computeScore(stars: number, hintsUsed: number, failedAttempts: number): number {
30:   return Math.max(50, 100 + stars * 50 - hintsUsed * 10 - Math.min(failedAttempts, 5) * 5);
31: }
32: 
33: export const RANKS = [
34:   { min: 0, name: "Penjelajah", emoji: "🧭" },
35:   { min: 800, name: "Petualang", emoji: "🗺️" },
36:   { min: 2000, name: "Jagoan Kode", emoji: "🦸" },
37: ] as const;
38: 
39: export function rankFor(xp: number) {
40:   let current: (typeof RANKS)[number] = RANKS[0];
41:   for (const r of RANKS) if (xp >= r.min) current = r;
42:   const idx = RANKS.indexOf(current);
43:   const next = RANKS[idx + 1];
44:   return { ...current, next: next ?? null };
45: }
46: 
47: export interface ProgressLite {
48:   missionId: string;
49:   completed: boolean;
50:   stars: number;
51:   bestScore: number;
52:   attempts: number;
53:   hintsUsed: number;
54: }
55: 
56: export function starsInLevel(level: number, progress: ProgressLite[]): number {
57:   const ids = new Set(missionsByLevel(level).map((m) => m.id));
58:   return progress.filter((p) => ids.has(p.missionId)).reduce((s, p) => s + p.stars, 0);
59: }
60: 
61: export function maxStarsInLevel(level: number): number {
62:   return missionsByLevel(level).length * 3;
63: }
64: 
65: export function starsNeededToUnlock(level: number): number {
66:   if (level <= 1) return 0;
67:   return Math.ceil(maxStarsInLevel(level - 1) * UNLOCK_RATIO);
68: }
69: 
70: export function isLevelUnlocked(level: number, progress: ProgressLite[]): boolean {
71:   if (level <= 1) return true;
72:   return isLevelUnlocked(level - 1, progress) && starsInLevel(level - 1, progress) >= starsNeededToUnlock(level);
73: }
74: 
75: export type MissionState = "locked" | "open" | "done";
76: 
77: export function missionState(missionId: string, progress: ProgressLite[]): MissionState {
78:   const mission = MISSIONS.find((m) => m.id === missionId);
79:   if (!mission) return "locked";
80:   const p = progress.find((x) => x.missionId === missionId);
81:   if (p?.completed) return "done";
82:   if (!isLevelUnlocked(mission.level, progress)) return "locked";
83:   const list = missionsByLevel(mission.level);
84:   const idx = list.findIndex((m) => m.id === missionId);
85:   if (idx === 0) return "open";
86:   const prev = progress.find((x) => x.missionId === list[idx - 1].id);
87:   return prev?.completed ? "open" : "locked";
88: }
89: 
90: export function totals(progress: ProgressLite[]) {
91:   const stars = progress.reduce((s, p) => s + p.stars, 0);
92:   const score = progress.reduce((s, p) => s + p.bestScore, 0);
93:   const completed = progress.filter((p) => p.completed).length;
94:   const currentLevel = [...LEVELS].reverse().find((l) => isLevelUnlocked(l.level, progress))?.level ?? 1;
95:   return { stars, score, xp: score, completed, currentLevel, rank: rankFor(score) };
96: }
97: 
98: /* ------------------------------ Badges ------------------------------ */
99: 
100: export interface BadgeDef {
101:   id: string;
102:   name: string;
103:   emoji: string;
104:   description: string;
105: }
106: 
107: export const BADGES: BadgeDef[] = [
108:   { id: "first-mission", name: "Misi Pertama", emoji: "🚀", description: "Menyelesaikan misi pertama" },
109:   { id: "no-hint", name: "Tanpa Petunjuk", emoji: "🧠", description: "Dapat 3 bintang tanpa bantuan Bibi" },
110:   { id: "seq-master", name: "Master Urutan", emoji: "👣", description: "Menyelesaikan semua misi Level 1" },
111:   { id: "loop-master", name: "Master Looping", emoji: "🔁", description: "Menyelesaikan semua misi Level 2" },
112:   { id: "if-master", name: "Master Kondisi", emoji: "🔀", description: "Menyelesaikan semua misi Level 3" },
113:   { id: "star-collector", name: "Pengumpul Bintang", emoji: "🌟", description: "Mengumpulkan 30 bintang" },
114:   { id: "perfect", name: "Sempurna", emoji: "💯", description: "Semua misi dengan 3 bintang" },
115: ];
116: 
117: export function badgeById(id: string) {
118:   return BADGES.find((b) => b.id === id);
119: }
120: 
121: /** Badges earned given updated progress and the latest attempt. */
122: export function evaluateBadges(
123:   progress: ProgressLite[],
124:   latest: { success: boolean; stars: number; hintsUsed: number },
125: ): string[] {
126:   const earned: string[] = [];
127:   const doneIds = new Set(progress.filter((p) => p.completed).map((p) => p.missionId));
128:   const levelDone = (lvl: number) => missionsByLevel(lvl).every((m) => doneIds.has(m.id));
129:   if (doneIds.size >= 1) earned.push("first-mission");
130:   if (latest.success && latest.stars === 3 && latest.hintsUsed === 0) earned.push("no-hint");
131:   if (levelDone(1)) earned.push("seq-master");
132:   if (levelDone(2)) earned.push("loop-master");
133:   if (levelDone(3)) earned.push("if-master");
134:   if (progress.reduce((s, p) => s + p.stars, 0) >= 30) earned.push("star-collector");
135:   if (MISSIONS.every((m) => progress.find((p) => p.missionId === m.id)?.stars === 3)) earned.push("perfect");
136:   return earned;
137: }
138: 
139: /* -------------------------- Concept mastery -------------------------- */
140: 
141: export type Mastery = "Sudah Paham" | "Sedang Belajar" | "Perlu Bantuan" | "Belum Mulai";
142: 
143: export interface AttemptLite {
144:   missionId: string;
145:   success: boolean;
146: }
147: 
148: export function conceptMastery(
149:   concept: Concept,
150:   progress: ProgressLite[],
151:   attempts: AttemptLite[],
152: ): { mastery: Mastery; completed: number; total: number; avgStars: number } {
153:   const level = LEVELS.find((l) => l.concept === concept)!.level;
154:   const missions = missionsByLevel(level);
155:   const ids = new Set(missions.map((m) => m.id));
156:   const prog = progress.filter((p) => ids.has(p.missionId));
157:   const done = prog.filter((p) => p.completed);
158:   const att = attempts.filter((a) => ids.has(a.missionId));
159:   const fails = att.filter((a) => !a.success).length;
160:   const avgStars = done.length ? done.reduce((s, p) => s + p.stars, 0) / done.length : 0;
161: 
162:   let mastery: Mastery;
163:   if (att.length === 0 && done.length === 0) mastery = "Belum Mulai";
164:   else if (done.length >= Math.ceil(missions.length * 0.8) && avgStars >= 2) mastery = "Sudah Paham";
165:   else if (fails >= 6 && fails > done.length * 3) mastery = "Perlu Bantuan";
166:   else mastery = "Sedang Belajar";
167: 
168:   return { mastery, completed: done.length, total: missions.length, avgStars };
169: }
